"use client";

import Image from "next/image";
import { ImageIcon } from "lucide-react";
import { useLanguage } from "../i18n/LanguageProvider";
import { menuCategories, type MenuCategory } from "@/lib/menu";

const menuCopy = {
  fr: { eyebrow: "La carte", title: "Notre menu", copy: "Découvrez tous nos plats, accompagnements, desserts et boissons.", navigation: "Catégories du menu", photo: "Photo à venir" },
  en: { eyebrow: "À la carte", title: "Our menu", copy: "Explore our full selection of dishes, sides, desserts and drinks.", navigation: "Menu categories", photo: "Photo coming soon" },
  de: { eyebrow: "À la carte", title: "Unsere Speisekarte", copy: "Entdecken Sie alle unsere Gerichte, Beilagen, Desserts und Getränke.", navigation: "Menükategorien", photo: "Foto folgt" },
};

const locales = { fr: "fr-FR", en: "en-IE", de: "de-DE" } as const;

function CategorySection({ category, nested = false }: { category: MenuCategory; nested?: boolean }) {
  const { language } = useLanguage();
  const copy = menuCopy[language];
  const formatPrice = (price: number) =>
    new Intl.NumberFormat(locales[language], { style: "currency", currency: "EUR" }).format(price);
  const Heading = nested ? "h3" : "h2";
  const DishHeading = nested ? "h4" : "h3";

  return (
    <section id={`menu-${category.id}`} aria-labelledby={`heading-${category.id}`} className="scroll-mt-28">
      <div className="mb-6 border-b border-white/10 pb-5">
        <Heading id={`heading-${category.id}`} className="text-3xl font-semibold text-white">{category.name[language]}</Heading>
        {category.note && <p className="mt-3 text-sm leading-6 text-zinc-400">{category.note[language]}</p>}
      </div>
      {category.items.length > 0 && <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
        {category.items.map((dish) => (
          <article key={dish.id} className="overflow-hidden rounded-2xl border border-white/10 bg-[#111111]">
            <div className="relative aspect-[16/9] border-b border-white/5 bg-gradient-to-br from-purple-950/30 to-zinc-900">
              {dish.image ? (
                <Image src={dish.image} alt={dish.name[language]} fill sizes="(min-width: 1024px) 33vw, (min-width: 640px) 50vw, 100vw" className="object-cover" />
              ) : (
                <div className="flex h-full flex-col items-center justify-center gap-3 text-zinc-500">
                  <ImageIcon aria-hidden="true" size={28} strokeWidth={1.25} />
                  <span lang={language} className="text-xs tracking-wide">{copy.photo}</span>
                </div>
              )}
            </div>
            <div className="p-5">
              <div className="flex items-start justify-between gap-4">
                <DishHeading className="text-lg font-semibold leading-6 text-white">{dish.name[language]}</DishHeading>
                {!dish.prices && <span className="shrink-0 text-sm font-medium leading-6 text-purple-300">{formatPrice(dish.price)}</span>}
              </div>
              {dish.description[language] && <p className="mt-3 text-sm leading-6 text-zinc-400">{dish.description[language]}</p>}
              {dish.prices && (
                <dl className="mt-4 space-y-2 border-t border-white/10 pt-4 text-sm">
                  {dish.prices.map((option) => (
                    <div key={option.label.fr} className="flex justify-between gap-3">
                      <dt className="text-zinc-400">{option.label[language]}</dt>
                      <dd className="shrink-0 font-medium text-purple-300">{formatPrice(option.price)}</dd>
                    </div>
                  ))}
                </dl>
              )}
            </div>
          </article>
        ))}
      </div>}
      {category.subcategories && (
        <div className="mt-10 space-y-12">
          <nav aria-label={`${copy.navigation}: ${category.name[language]}`} className="flex flex-wrap gap-3">
            {category.subcategories.map((subcategory) => (
              <a key={subcategory.id} href={`#menu-${subcategory.id}`} className="rounded-full border border-purple-500/30 px-4 py-2 text-sm text-purple-300 transition hover:border-purple-400 hover:text-white">
                {subcategory.name[language]}
              </a>
            ))}
          </nav>
          {category.subcategories.map((subcategory) => (
            <CategorySection key={subcategory.id} category={subcategory} nested />
          ))}
        </div>
      )}
    </section>
  );
}

export default function FullMenu() {
  const { language } = useLanguage();
  const copy = menuCopy[language];

  return (
    <section id="menu" className="relative scroll-mt-20 bg-[#090909] pb-24 pt-36 md:pb-32 md:pt-44">
      <div className="mx-auto max-w-6xl px-5 sm:px-8">
        <div className="mx-auto mb-12 max-w-3xl text-center">
          <p className="text-sm uppercase tracking-[0.4em] text-purple-400">{copy.eyebrow}</p>
          <h1 className="mt-6 text-5xl font-bold leading-tight text-white md:text-7xl">{copy.title}</h1>
          <p className="mt-6 text-lg leading-8 text-zinc-400">{copy.copy}</p>
        </div>
        <nav aria-label={copy.navigation} className="mb-16 flex flex-wrap justify-center gap-2" lang={language}>
          {menuCategories.map((category) => (
            <a key={category.id} href={`#menu-${category.id}`} className="rounded-full border border-white/15 px-4 py-2 text-sm text-zinc-300 transition hover:border-purple-500 hover:text-white focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-purple-400">
              {category.name[language]}
            </a>
          ))}
        </nav>
        <div className="space-y-16" lang={language}>
          {menuCategories.map((category) => (
            <CategorySection key={category.id} category={category} />
          ))}
        </div>
      </div>
    </section>
  );
}
